-- INHERE initial CMS content migration
-- Run after schema.sql. Safe to run again: records update by slug/key.

on conflict(page_key) do update set title_en=excluded.title_en,title_vi=excluded.title_vi,subtitle_en=excluded.subtitle_en,subtitle_vi=excluded.subtitle_vi,body_en=excluded.body_en,body_vi=excluded.body_vi,hero_image=excluded.hero_image,updated_at=now();

on conflict(slug) do update set title_en=excluded.title_en,title_vi=excluded.title_vi,description_en=excluded.description_en,description_vi=excluded.description_vi,image_url=excluded.image_url,price_label=excluded.price_label,sort_order=excluded.sort_order,updated_at=now();

on conflict(slug) do update set title_en=excluded.title_en,title_vi=excluded.title_vi,category_en=excluded.category_en,category_vi=excluded.category_vi,description_en=excluded.description_en,description_vi=excluded.description_vi,cover_image=excluded.cover_image,sort_order=excluded.sort_order,updated_at=now();

on conflict(slug) do update set title_en=excluded.title_en,title_vi=excluded.title_vi,excerpt_en=excluded.excerpt_en,excerpt_vi=excluded.excerpt_vi,content_en=excluded.content_en,content_vi=excluded.content_vi,category_en=excluded.category_en,category_vi=excluded.category_vi,cover_image=excluded.cover_image,status='published',published_at=coalesce(public.blog_posts.published_at,now()),updated_at=now();

on conflict(slug) do update set title_en=excluded.title_en,title_vi=excluded.title_vi,description_en=excluded.description_en,description_vi=excluded.description_vi,category_en=excluded.category_en,category_vi=excluded.category_vi,duration_label=excluded.duration_label,price_label=excluded.price_label,image_url=excluded.image_url,sort_order=excluded.sort_order,updated_at=now();

on conflict(slug) do update set type=excluded.type,title_en=excluded.title_en,title_vi=excluded.title_vi,description_en=excluded.description_en,description_vi=excluded.description_vi,image_url=excluded.image_url,price_label=excluded.price_label,sort_order=excluded.sort_order,updated_at=now();

