insert into public.blog_posts(slug,title_en,title_vi,excerpt_en,excerpt_vi,content_en,content_vi,category_en,category_vi,cover_image,status,published_at)
values
('best-places-for-a-photoshoot-in-hoi-an','Best Places for a Photoshoot in Hội An','Những địa điểm chụp ảnh đẹp nhất Hội An','A thoughtful guide to beautiful corners, quieter streets and the changing light of the Old Town.','Hướng dẫn về những góc đẹp, con phố yên tĩnh và ánh sáng thay đổi của Phố Cổ.','Hội An changes character throughout the day. Early mornings feel intimate and quiet, while late afternoon brings warmth to ochre walls and river reflections.','Hội An thay đổi vẻ đẹp theo từng thời điểm trong ngày. Buổi sáng sớm yên bình, buổi chiều mang ánh sáng ấm áp lên những bức tường vàng và mặt sông.','Photography Locations','Địa điểm chụp ảnh','https://images.unsplash.com/photo-1780803244219-a21588279fc6?auto=format&fit=crop&w=1800&q=90','published',now()),
('what-to-wear-for-an-ao-dai-photoshoot','What to Wear for an Ao Dai Photoshoot','Mặc gì khi chụp ảnh Áo dài','How to choose color, silhouette and accessories that feel personal and photograph beautifully.','Cách chọn màu sắc, kiểu dáng và phụ kiện phù hợp để lên hình thật đẹp.','Choose an Ao Dai that allows comfortable movement and complements both your skin tone and the colors of Hội An.','Hãy chọn Áo dài thoải mái, phù hợp với màu da và sắc màu của Hội An.','Ao Dai','Áo dài','https://images.unsplash.com/photo-1768017093154-1bfbaa3e3ccf?auto=format&fit=crop&w=1800&q=90','published',now()),
('golden-hour-photography-in-hoi-an','Golden Hour Photography in Hội An','Chụp ảnh giờ vàng tại Hội An','Plan a relaxed session around soft riverside light and warm lantern-lit streets.','Lên kế hoạch cho buổi chụp nhẹ nhàng bên ánh sáng bờ sông và những con phố đèn lồng.','Golden hour brings gentle dimension to portraits and turns the Old Town into a warm, cinematic setting.','Giờ vàng tạo chiều sâu dịu dàng cho chân dung và biến Phố Cổ thành khung cảnh điện ảnh ấm áp.','Photoshoot Tips','Mẹo chụp ảnh','https://images.unsplash.com/photo-1528181304800-259b08848526?auto=format&fit=crop&w=1800&q=90','published',now())
